@PostMapping("/pay/notify")
public ResponseEntity<String> notify(@RequestBody String body, @RequestHeader HttpHeaders headers) {
    PayNotify n = payClient.verifyAndDecrypt(body, headers);   // 1. 验签 + 解密，失败抛异常
    Order order = orderMapper.findByNo(n.outTradeNo());
    if (order == null || order.getAmount() != n.totalFee()) {  // 2. 校验订单与金额（单位：分）
        log.warn("notify mismatch {}", n);
        return ResponseEntity.badRequest().body("FAIL");
    }
    orderService.markPaid(n);                                   // 3. 幂等处理
    return ResponseEntity.ok("SUCCESS");                        // 4. 按平台要求格式应答
}

@Transactional(rollbackFor = Exception.class)
public void markPaid(PayNotify n) {
    int rows = orderMapper.updateStatus(n.outTradeNo(), "WAIT_PAY", "PAID", n.transactionId());
    if (rows == 0) return;                                      // 已处理过，直接成功
    outboxMapper.insert(Outbox.of("order-paid", n.outTradeNo())); // 后续动作异步、可靠
}
